<template><el-button text @click="start">举报{{name}}</el-button><el-dialog v-model="open" append-to-body :title="'举报'+name" width="min(420px,90vw)"><el-input v-model="reason" maxlength="120" placeholder="举报原因"/><el-input v-model="description" type="textarea" maxlength="1000" placeholder="补充说明（选填）"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :disabled="!reason.trim()||busy" @click="send">提交举报</el-button></template></el-dialog></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {reportTarget} from '@/api/campushub';import {useAuthStore} from '@/stores/auth';const props=defineProps<{kind:'SHOP'|'PROJECT_AD';id:number}>(),auth=useAuthStore(),router=useRouter(),route=useRoute(),open=ref(false),reason=ref(''),description=ref(''),busy=ref(false),name=computed(()=>props.kind==='SHOP'?'店铺':'宣传');watch([()=>auth.token,()=>props.id],()=>{open.value=false;reason.value='';description.value=''});function start(){if(!auth.currentUser){void router.push({name:'auth',query:{redirect:route.fullPath}});return}reason.value='';description.value='';open.value=true}async function send(){if(busy.value||!reason.value.trim()||!auth.currentUser)return;busy.value=true;try{await reportTarget(auth.currentUser.id,{targetType:props.kind,targetId:props.id,reason:reason.value.trim(),description:description.value});open.value=false;ElMessage.success('举报已提交')}catch(e){ElMessage.error(e instanceof Error?e.message:'提交失败')}finally{busy.value=false}}
</script>
